cd /tmp/vally-eval-trial-F3cnvh && cat > .copilot-tracking/skraft-plans/pricing/features/pricing-loyalty-discount.feature <<'E'
@loyalty-discount
Feature: Loyalty tier pricing
  A returning customer's loyalty tier is reflected in the checkout total.

  # SETTLED: Bronze, Silver, Gold (AC-1..AC-3). Source: ac.md
  # NOT SETTLED: AC-4 rounding and the Platinum reduction (see below)

  @happy-path @smoke
  Scenario Outline: Returning customer is charged the price of their loyalty tier
    Given a returning customer in the <tier> tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged <charged> cents

    Examples:
      | tier   | charged |
      | Bronze | 9500    |
      | Silver | 9000    |
      | Gold   | 8500    |

  # OPEN QUESTION - escalate to DISCUSS before implementing.
  # ac.md AC-4 is titled "reduction lands on a whole cent in the customer's favour",
  # but its value (7 charged on a 7 subtotal = zero reduction) favours the business:
  # 5% of 7 is 0.35 cent, and rounding the reduction in the customer's favour gives 1 cent,
  # so 6 charged. The value below is copied verbatim from AC-4; title and value disagree.
  @edge-case @pending-clarification
  Scenario: Bronze customer with a tiny basket is charged a whole number of cents
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # NOT DECIDED - intentionally no scenario and no value.
  # Platinum: the business has not agreed a reduction (ac.md "Not decided",
  # stories-m1.md scope). Any expected value here would invent a business decision.
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Returning customer is charged the price of their loyalty tier (AC-1)
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
E
echo done

